"""Direct regular quads for a cap step below the existing outline error budget.

The two corners of the short step are replaced by their midpoint in the outer
front only. The body seam is copied exactly. Both the original front and the
constructed front are piecewise linear functions of the transverse coordinate;
checking their combined knots bounds the complete boundary in both directions.
No tolerance is enlarged and the ordinary quad-shape guard still applies.
"""
import bpy
from .path_surface_nodes import _Nodes
from . import boundary_quad_bridge_nodes as bridge, bundle_cap_step_nodes as step

NAME = 'Prochitecture Streets / Bounded microstep cap quads v1'
OUTLINE_TOLERANCE = 4e-6


def build():
    if NAME in bpy.data.node_groups:
        return bpy.data.node_groups[NAME]
    tree = bpy.data.node_groups.new(NAME, 'GeometryNodeTree'); g = _Nodes(tree)
    for name in ('Top', 'Concave', 'Convex', 'Bottom', 'Cut Top', 'Cut Bottom'):
        tree.interface.new_socket(name=name, in_out='INPUT', socket_type='NodeSocketVector')
    tree.interface.new_socket(name='Seam', in_out='INPUT', socket_type='NodeSocketGeometry')
    tree.interface.new_socket(name='Cell Size', in_out='INPUT', socket_type='NodeSocketFloat').default_value = .17
    for name, kind in (('Geometry', 'Geometry'), ('Valid', 'Bool'), ('Boundary Error', 'Float')):
        tree.interface.new_socket(name=name, in_out='OUTPUT', socket_type='NodeSocket'+kind)
    inp = g.node('NodeGroupInput', 'Original physical cap and exact body seam')
    out = g.node('NodeGroupOutput', 'Bounded microstep approximation')
    add = lambda a, b: g.math('ADD', a, b)
    sub = lambda a, b: g.math('SUBTRACT', a, b)
    mul = lambda a, b: g.math('MULTIPLY', a, b)
    div = lambda a, b: g.math('DIVIDE', a, b)
    x = lambda p: g.component(p, 'X')
    y = lambda p: g.component(p, 'Y')
    mix = lambda a, b, t: g.vector('ADD', a, g.vector('SCALE', g.vector('SUBTRACT', b, a), t))
    origin = inp.outputs['Convex']; delta = g.vector('SUBTRACT', inp.outputs['Concave'], origin)
    length = g.vector('LENGTH', delta); forward = g.vector('NORMALIZE', delta)
    across = g.vector('CROSS_PRODUCT', (0., 0., 1.), forward)
    reflected = g.compare(g.vector('DOT_PRODUCT', g.vector('SUBTRACT', inp.outputs['Top'],
                         inp.outputs['Concave']), across), 0., 'LESS_THAN')
    across = g.vector('SCALE', across, g.switch(reflected, 1., -1.))

    def local(p):
        d = g.vector('SUBTRACT', p, origin)
        return g.xyz(g.vector('DOT_PRODUCT', d, forward), g.vector('DOT_PRODUCT', d, across))

    def original(p):
        # The frame comes from float32 normalization; compensate its squared
        # length on reconstruction as in the exact stepped cap constructor.
        inverse = div(1., g.vector('DOT_PRODUCT', forward, forward))
        return g.vector('ADD', origin, g.vector('SCALE', g.vector('ADD',
            g.vector('SCALE', forward, x(p)), g.vector('SCALE', across, y(p))), inverse))

    top, bottom, cut_top, cut_bottom = [local(inp.outputs[n]) for n in ('Top', 'Bottom', 'Cut Top', 'Cut Bottom')]
    pos = g.node('GeometryNodeInputPosition', 'Cap and seam coordinates').outputs[0]
    index = g.node('GeometryNodeInputIndex', 'Ordered row or mesh vertex').outputs[0]
    order = g.node('GeometryNodeSortElements', 'Order the body seam in the step frame'); order.domain = 'POINT'
    g.set(inp.outputs['Seam'], order.inputs['Geometry']); g.set(mul(-1., y(local(pos))), order.inputs['Sort Weight'])
    seam = order.outputs['Geometry']; count = bridge._size(g, seam)
    current_y = y(local(pos))
    previous_y = y(local(g.sample(seam, pos, g.math('MAXIMUM', 0., sub(index, 1.)), 'FLOAT_VECTOR')))
    monotone = g.either(g.compare(index, 0.), g.compare(sub(previous_y, current_y), 1e-7, 'GREATER_THAN'))
    cut_line = g.vector('SUBTRACT', cut_bottom, cut_top)
    residual = div(g.math('ABSOLUTE', g.component(g.vector('CROSS_PRODUCT',
        g.vector('SUBTRACT', local(pos), cut_top), cut_line), 'Z')), g.vector('LENGTH', cut_line))
    checks = [g.compare(length, 0., 'GREATER_THAN'), g.compare(count, 2., 'GREATER_EQUAL'),
        g.compare(y(top), 0., 'GREATER_THAN'), g.compare(y(bottom), 0., 'LESS_THAN'),
        g.compare(y(cut_top), y(cut_bottom), 'GREATER_THAN'), g.stat(seam, monotone),
        g.compare(g.stat(seam, residual, output='Max'), OUTLINE_TOLERANCE, 'LESS_EQUAL')]
    for at, target in ((0, inp.outputs['Cut Top']), (sub(count, 1.), inp.outputs['Cut Bottom'])):
        checks.append(g.compare(g.vector('DISTANCE', g.sample(seam, pos, at, 'FLOAT_VECTOR'),
                                target), OUTLINE_TOLERANCE, 'LESS_EQUAL'))

    midpoint = g.xyz(mul(.5, length))
    v = div(sub(current_y, y(cut_top)), sub(y(cut_bottom), y(cut_top)))
    ordinate = add(y(top), mul(sub(y(bottom), y(top)), v))
    front = g.switch(g.compare(ordinate, 0., 'GREATER_THAN'),
        mix(midpoint, bottom, div(ordinate, y(bottom))),
        mix(midpoint, top, div(ordinate, y(top))), 'VECTOR')
    # Keep the physical outer endpoints exact rather than reconstructing them
    # through a transverse fraction with rounded arithmetic.
    front = g.switch(g.compare(index, 0.), front, top, 'VECTOR')
    front = g.switch(g.compare(index, sub(count, 1.)), front, bottom, 'VECTOR')
    front_rows = bridge._position(g, seam, front)
    ordinate = y(pos)
    physical = g.switch(g.compare(ordinate, 0., 'GREATER_THAN'),
        mix(g.xyz(), bottom, div(ordinate, y(bottom))),
        mix(g.xyz(length), top, div(ordinate, y(top))), 'VECTOR')
    error = g.stat(front_rows, g.vector('DISTANCE', pos, physical), output='Max')
    lookup = bridge._position(g, front_rows, g.xyz(0., ordinate))
    # Also check all original knots. The difference is affine between this
    # combined set and the constructed row knots, so no interior maximum is
    # omitted. Both endpoints of the original horizontal step are included.
    for knot in (top, g.xyz(length), g.xyz(), bottom):
        nearest = g.node('GeometryNodeSampleNearest', 'Bracket original front knot by transverse row')
        nearest.domain = 'POINT'; g.set(lookup, nearest.inputs['Geometry'])
        g.set(g.xyz(0., y(knot)), nearest.inputs['Sample Position'])
        at = nearest.outputs['Index']; first = g.sample(front_rows, pos, at, 'FLOAT_VECTOR')
        other = g.math('MINIMUM', sub(count, 1.), g.math('MAXIMUM', 0.,
            add(at, g.switch(g.compare(y(knot), y(first), 'GREATER_THAN'), 1., -1.))))
        last = g.sample(front_rows, pos, other, 'FLOAT_VECTOR')
        t = div(sub(y(knot), y(first)), sub(y(last), y(first)))
        projected = mix(first, last, g.math('MINIMUM', 1., g.math('MAXIMUM', 0., t)))
        error = g.math('MAXIMUM', error, g.vector('DISTANCE', knot, projected))
    g.set(error, out.inputs['Boundary Error'])
    depths = [g.vector('DISTANCE', inp.outputs[a], inp.outputs[b])
              for a, b in (('Top', 'Cut Top'), ('Bottom', 'Cut Bottom'))]
    nx_raw = g.math('MAXIMUM', 1., g.math('CEIL', div(g.math('MAXIMUM', *depths), inp.outputs['Cell Size'])))
    eligible = g.all(*checks, g.compare(error, OUTLINE_TOLERANCE, 'LESS_EQUAL'),
        g.compare(inp.outputs['Cell Size'], 0., 'GREATER_THAN'), g.compare(nx_raw, 4096., 'LESS_EQUAL'),
        g.compare(count, 4097., 'LESS_EQUAL'), g.compare(mul(nx_raw, sub(count, 1.)), 65536., 'LESS_EQUAL'))
    nx = g.switch(eligible, 1., nx_raw); ny = g.switch(eligible, 1., sub(count, 1.))
    grid = g.node('GeometryNodeMeshGrid', 'Direct bounded-front quads, exact body row')
    g.set(add(nx, 1.), grid.inputs['Vertices X']); g.set(add(ny, 1.), grid.inputs['Vertices Y'])
    stride = add(ny, 1.); row = g.math('FLOORED_MODULO', index, stride)
    column = g.math('FLOOR', div(index, stride)); u = div(column, nx)
    edge = original(g.sample(front_rows, pos, row, 'FLOAT_VECTOR'))
    edge = g.switch(g.compare(row, 0.), edge, inp.outputs['Top'], 'VECTOR')
    edge = g.switch(g.compare(row, sub(count, 1.)), edge, inp.outputs['Bottom'], 'VECTOR')
    body = g.sample(seam, pos, row, 'FLOAT_VECTOR'); at_body = g.compare(column, nx)
    position = g.switch(at_body, mix(edge, body, u), body, 'VECTOR')
    mesh = bridge._position(g, grid.outputs['Mesh'], position)
    body_id = g.sample(seam, g.named('st_cap_body_index'), row, 'INT')
    mesh = g.store(mesh, 'st_cap_body_index', g.switch(at_body, -1, body_id, 'INT'), 'INT')
    flip = g.node('GeometryNodeFlipFaces', 'Positive microstep cap winding')
    g.set(mesh, flip.inputs['Mesh']); g.set(g.boolean('NOT', reflected), flip.inputs['Selection']); mesh = flip.outputs['Mesh']
    valid = g.all(eligible, step.shape_good(g, mesh))
    g.set(valid, out.inputs['Valid']); g.set(g.switch(valid, None, mesh, 'GEOMETRY'), out.inputs['Geometry'])
    return tree
